  L.push("");

  /* ------------------------------------------------------ 18 Sudarshana */
  bphsH(L, 2, "§18 — PROMISE LAYER 7: the Sudarshana Chakra (Ch. 74)");
  var sud = bphsSudarshana(C);
  L.push("- " + sud.gate);
  L.push("");
